#include "tasks/AdvancedRecipeTask.hpp"
#include "content/Canonical.hpp"
#include <fstream>
#include <iostream>
using namespace fathom;using namespace tasks::advanced;using V=json::Value;using O=V::Object;
int checks=0,commands=0,rows=0;void ck(bool b,const char*m){++checks;if(!b)throw std::runtime_error(m);}template<class F>void no(F f){bool bad=false;try{f();}catch(const std::exception&){bad=true;}ck(bad,"expected refusal");}
template<class T>void round(T&t){const auto bytes=t.continuation();const auto&d=t.retainedDefinition();auto r=T::restoreContinuation(d,bytes);ck(r->continuation()==bytes&&r->learnerView()==t.learnerView(),"native replay parity");auto old=t.capture(
 []{if constexpr(std::is_same_v<T,AdvancedRecipeTask>)return Action::Cancel;else return std::string("cancel");}());no([&]{r->apply(old,O{});});
 auto altered=json::parse(bytes);altered.object().at("body").object().at("state").object().at("revision")=V::fromInteger(999999);altered.object().at("sha256")=content::sha256(json::stringify(altered.object().at("body")));no([&]{T::restoreContinuation(d,json::stringify(altered));});ck(t.continuation()==bytes,"original retained");}
int main(int argc,char**argv){try{ck(argc==4,"three exact retained trace paths");for(int file=1;file<4;++file){std::ifstream in(argv[file]);ck(in.good(),"trace file");std::string line;while(std::getline(in,line)){auto row=json::parse(line);const auto&d=definition(row.object().at("source_key").string());++rows;
 if(file==1){AdvancedRecipeTask t(d);round(t);ck(t.fenceInactiveForNavigation(),"initial fence");round(t);for(const auto&step:row.object().at("trace").array()){auto a=transferAction(step.object().at("action").string());t.apply(t.capture(a),step.object().at("payload"));++commands;ck(t.learnerView()==step.object().at("learner_view_after"),"source trace transfer parity");round(t);}if(t.fenceInactiveForNavigation())round(t);}
 else{AdvancedRecipeWorkflow t(d);round(t);ck(t.fenceInactiveForNavigation(),"initial fence");round(t);int n=0;for(const auto&step:row.object().at("trace").array()){const auto a=step.object().at("action").string();auto token=t.capture(a);const auto before=t.continuation();if(step.find("refuse")&&step.find("refuse")->boolean()){no([&]{t.apply(token,step.object().at("payload"));});ck(t.continuation()==before,"refusal retained journal");}else{t.apply(token,step.object().at("payload"));++commands;}ck(t.learnerView()==step.object().at("learner_view_after"),"source trace workflow parity");if(++n%25==0||a=="navigate"||a=="release"||a=="reveal")round(t);}round(t);if(t.fenceInactiveForNavigation())round(t);}
 }}std::cout<<"PASS "<<checks<<" advanced private replay checks; "<<rows<<" retained traces, "<<commands<<" legal commands; no GUI/audio/credit\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<" checks="<<checks<<" rows="<<rows<<" commands="<<commands<<'\n';return 1;}}
